package com.meetspace.realtime; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.stereotype.Component; import org.springframework.transaction.event.*; @Component public class BookingRealtimePublisher{private final SimpMessagingTemplate t;public BookingRealtimePublisher(SimpMessagingTemplate t){this.t=t;}@TransactionalEventListener(phase=TransactionPhase.AFTER_COMMIT) public void publish(RealtimeEvent e){t.convertAndSend("/topic/rooms/availability",new RealtimeEvent(null,"ROOM_AVAILABILITY_CHANGED",null,e.roomId(),e.bookingDate(),null,null,null,e.timestamp()));t.convertAndSendToUser(e.ownerName(),"/queue/bookings",e);}}